style.css:
@-moz-document domain("google.com") {
/* ★ 星アイコンと数値（例：4.1）を非表示 */
  span[aria-hidden="true"] svg[aria-label*="stars"],
  span[class*="MW4etd"],
  span[jscontroller][class*="fontBodyMedium"],
  div[aria-label*="評価"],
  div[class*="fontHeadlineSmall"][jsname] {
    display: none !important;
  }

  /* クチコミ（レビュー）本文やリスト自体を非表示 */
  div[data-review-id],
  div[jscontroller][jsaction*="mouseover:"],
  div[jscontroller][jsaction*="mouseenter:"],
  div[jscontroller*="OxjKxc"] {
    display: none !important;
  }

  /* クチコミというタブやボタンも非表示 */
  button[aria-label*="クチコミ"],
  a[href*="reviews"],
  div[role="tab"][aria-label*="クチコミ"],
  div[role="button"][aria-label*="クチコミ"],
  div[class*="review-chip"] {
    display: none !important;
  }

  /* スマホ版で星評価が出る位置対応（柔軟性のあるマッチ） */
  div[aria-label*="星"] {
    display: none !important;
  }

  /* 店舗名下の星ごと評価が載ってる場合も消す */
  div[class*="gm2-subtitle-alt-1"],
  span[class*="gm2-caption"],
  span[class*="section-star-display"] {
    display: none !important;
  }
}
